# Find unique colored bands by scanning outward to inward
def get_layer_colors(region):
    """Extract colors layer by layer from outside in"""
    colors_by_layer = {}
    layer_num = 0

    # Get bounding box
    rows = len(region)
    cols = len(region[0])

    # Scan perimeter for first layer
    top_row = region[0]
    bottom_row = region[-1]
    left_col = [region[i][0] for i in range(rows)]
    right_col = [region[i][-1] for i in range(rows)]

    unique_perimeter = set()
    for cell in top_row + bottom_row + left_col + right_col:
        if cell != 0:
            unique_perimeter.add(cell)

    colors_by_layer[layer_num] = sorted(unique_perimeter)
    layer_num += 1

    # Inner region after removing one border
    inner_rows = range(1, rows-1)
    inner_cols = range(1, cols-1)
    if min(inner_rows.start, inner_rows.stop-1) > 0:
        inner_region = []
        for r in inner_rows:
            inner_row = []
            for c in inner_cols:
                inner_row.append(region[r][c])
            inner_region.append(inner_row)

        inner_perimeter = set()
        if inner_region:
            for cell in inner_region[0] + inner_region[-1]:
                if cell != 0:
                    inner_perimeter.add(cell)
            for c in range(len(inner_region[0])):
                if len(inner_region) > 1:
                    inner_perimeter.add(inner_region[1][c])
                else:
                    break
            for c in range(len(inner_region[0])-1, -1, -1):
                if len(inner_region) > 1:
                    inner_perimeter.add(inner_region[-2][c])
                else:
                    break

        if inner_perimeter:
            colors_by_layer[layer_num] = sorted(list(inner_perimeter))
            layer_num += 1

    return colors_by_layer

